use vstd::prelude::*;

verus! {

fn atleast_2d(arr: Vec<f32>) -> (result: Vec<Vec<f32>>)
    ensures
        // The outer vector has exactly one row
        result.len() == 1,
        // That single row is element‐wise equal to the input array
        result[0] == arr,
{
    // Build the single row by copying elements of `arr`
    let mut row: Vec<f32> = Vec::new();
    let mut i: usize = 0;
    while i < arr.len()
        invariant
            // We never overshoot the length of `arr`
            i <= arr.len(),
            // The length of `row` grows in lockstep with `i`
            row.len() == i,
            // Every element copied so far matches the original
            forall j: usize :: j < row.len() ==> row[j] == arr[j],
        decreases
            arr.len() - i
    {
        row.push(arr[i]);
        i += 1;
    }

    // Now `row` has the same length and contents as `arr`.
    // Wrap it in an outer vector of length exactly 1.
    let mut out: Vec<Vec<f32>> = Vec::new();
    out.push(row);

    // Assign to the named result variable
    result = out;
}

}   // end verus!

